35	const formatTimestamp = (timestamp: bigint | undefined) => {
36	  if (!timestamp) return "";
37	
38	  const date = new Date(Number(Number(timestamp)));
39	
40	  if (isToday(date)) return format(date, "HH:mm");
41	
42	  if (isYesterday(date)) return "Yesterday";
43	
44	  if (isThisWeek(date)) return format(date, "EEEE");
45	
46	  return format(date, "d. M. yyyy.");
47	};
